using J=nlohmann::json;
static std::vector<unsigned char> imageBytes(const J &request){
 auto text=request.at("image_data").get<std::string>();
 if(text.empty()||text.size()>2800000||text.size()%4)throw std::runtime_error("Invalid image upload (maximum 2 MB).");
 const std::string alphabet="ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";std::vector<unsigned char> bytes;unsigned bits=0;int count=0;bool padding=false;
 for(char c:text){if(c=='='){padding=true;continue;}auto n=alphabet.find(c);if(padding||n==std::string::npos)throw std::runtime_error("Invalid image encoding.");bits=(bits<<6)|unsigned(n);count+=6;if(count>=8){count-=8;bytes.push_back((bits>>count)&255);}}
 uint32_t w,h;if(!coverDimensions(bytes,w,h))throw std::runtime_error("Choose a JPEG or PNG image up to 4096 pixels.");return bytes;
}
static std::string trim(std::string s){auto a=s.find_first_not_of(" \t\r\n"),b=s.find_last_not_of(" \t\r\n");return a==s.npos?"":s.substr(a,b-a+1);}
static std::string bounded(const J &j,const char *key,size_t max,bool required=false){if(!j.contains(key)){if(required)throw std::runtime_error(std::string("Missing ")+key);return {}; }if(!j[key].is_string())throw std::runtime_error("Invalid text field.");auto s=trim(j[key].get<std::string>());if(s.size()>max||(required&&s.empty())||s.find('\0')!=s.npos)throw std::runtime_error(std::string("Invalid ")+key);return s;}
J sourceReference(const Source &s){return {{"smb",s.smb},{"root",s.root},{"server",s.share.server},{"share",s.share.share},{"user",s.share.user}};}
bool resolveReference(const J &ref,const Settings &settings,Source &out,std::string &error){try{if(ref.value("smb",false)){for(auto &s:settings.shares)if(s.server==ref.value("server","")&&s.share==ref.value("share","")&&s.user==ref.value("user","")){out={true,s,ref.at("root")};return true;}error="SMB share is unavailable. Add it again in Files.";return false;}out={false,{},ref.at("root")};return true;}catch(...){error="Invalid saved album source.";return false;}}
struct HTTPBuffer{std::vector<unsigned char> *out;size_t limit;bool probe;};
static size_t httpWrite(char *p,size_t a,size_t b,void *v){auto &s=*static_cast<HTTPBuffer*>(v);size_t n=a*b;if(s.out->size()+n>s.limit){if(s.probe){s.out->insert(s.out->end(),p,p+std::min(n,s.limit-s.out->size()));}return 0;}s.out->insert(s.out->end(),p,p+n);return n;}
int collectionHTTP(const std::string &url,std::vector<unsigned char> &out,size_t limit,bool probe){out.clear();if(!httpURL(url))return 0;auto *c=curl_easy_init();if(!c)return 0;HTTPBuffer buffer{&out,limit,probe};std::string ca=std::string(assetRoot())+"cacert.pem";curl_easy_setopt(c,CURLOPT_CAINFO,ca.c_str());curl_easy_setopt(c,CURLOPT_URL,url.c_str());curl_easy_setopt(c,CURLOPT_PROTOCOLS,long(CURLPROTO_HTTP|CURLPROTO_HTTPS));curl_easy_setopt(c,CURLOPT_REDIR_PROTOCOLS,long(CURLPROTO_HTTP|CURLPROTO_HTTPS));curl_easy_setopt(c,CURLOPT_FOLLOWLOCATION,1L);curl_easy_setopt(c,CURLOPT_MAXREDIRS,5L);curl_easy_setopt(c,CURLOPT_CONNECTTIMEOUT,6L);curl_easy_setopt(c,CURLOPT_TIMEOUT,probe?8L:12L);curl_easy_setopt(c,CURLOPT_NOSIGNAL,1L);curl_easy_setopt(c,CURLOPT_USERAGENT,"NX-Hi-Fi/2.0.0 (https://github.com/Anime0t4ku/NX-HI-FI)");curl_easy_setopt(c,CURLOPT_WRITEFUNCTION,httpWrite);curl_easy_setopt(c,CURLOPT_WRITEDATA,&buffer);auto r=curl_easy_perform(c);long status=0;curl_easy_getinfo(c,CURLINFO_RESPONSE_CODE,&status);curl_easy_cleanup(c);if(r!=CURLE_OK&&!(probe&&r==CURLE_WRITE_ERROR&&!out.empty()))return 0;return int(status);}
static std::string escape(const std::string &s){static const char hex[]="0123456789ABCDEF";std::string out;for(unsigned char c:s){if(std::isalnum(c)||c=='-'||c=='_'||c=='.')out+=c;else{out+='%';out+=hex[c>>4];out+=hex[c&15];}}return out;}
static void coverWrite(const std::string &path,const std::vector<unsigned char> &bytes){if(bytes.empty())return;std::ofstream f(path+".tmp",std::ios::binary);f.write((const char*)bytes.data(),bytes.size());f.close();if(f)std::rename((path+".tmp").c_str(),path.c_str());}
CollectionStore::CollectionStore(std::string dir,Fetch http):fetch(std::move(http)),directory(std::move(dir)){
 mkdir(directory.c_str(),0700);mkdir((directory+"/album-art").c_str(),0700);
 data={{"revision",1},{"libraries",J::array()},{"albums",J::array()},{"stations",J::array()},{"playlists",J::array()}};
 std::ifstream f(directory+"/library.json");if(f){try{J saved;f>>saved;if(saved.is_object()&&saved.value("libraries",J{}).is_array()&&saved.value("albums",J{}).is_array()&&saved.value("stations",J{}).is_array()){data=std::move(saved);for(auto &a:data["albums"])if(a.value("busy",false)){a["busy"]=false;a["status"]="Scan interrupted; refresh album.";}}else message="Invalid collection file; original file kept.";}catch(...){message="Cannot read collection; original file kept.";}}
 if(!data.contains("playlists")||!data["playlists"].is_array())data["playlists"]=J::array();
 serial=std::chrono::system_clock::now().time_since_epoch().count();thread=std::thread(&CollectionStore::loop,this);
}
CollectionStore::~CollectionStore(){{std::lock_guard<std::mutex> l(mutex);quit=true;jobs.clear();}cv.notify_all();thread.join();}
void CollectionStore::loop(){for(;;){std::function<void()> job;{std::unique_lock<std::mutex> l(mutex);cv.wait(l,[&]{return quit||!jobs.empty();});if(quit)return;job=std::move(jobs.front());jobs.pop_front();}try{job();}catch(const std::exception &e){std::lock_guard<std::mutex> l(mutex);message=e.what();}}}
void CollectionStore::enqueue(std::function<void()> f){if(jobs.size()>=32)throw std::runtime_error("Collection task queue is full; wait for current scans.");jobs.push_back(std::move(f));cv.notify_one();}
std::string CollectionStore::nextID(){return std::to_string(++serial);}
bool CollectionStore::saveLocked(std::string &error){auto path=directory+"/library.json";std::ofstream f(path+".tmp",std::ios::binary);if(!f){error="Cannot save collections.";return false;}f<<data.dump(2)<<'\n';f.flush();bool good=bool(f);f.close();if(!good||std::rename((path+".tmp").c_str(),path.c_str())){error="Cannot save collections.";return false;}return true;}
uint64_t CollectionStore::revision()const{std::lock_guard<std::mutex> l(mutex);return data.value("revision",uint64_t(1));}
J CollectionStore::snapshot()const{std::lock_guard<std::mutex> l(mutex);auto copy=data;copy["message"]=message;return copy;}
std::string CollectionStore::coverPath(const std::string &id)const{if(id.empty()||id.size()>32||id.find_first_not_of("0123456789")!=id.npos)return {};return directory+"/album-art/"+id+".jpg";}
std::string CollectionStore::imagePath(const std::string &type,const std::string &id)const{if((type!="station"&&type!="collection"&&type!="playlist")||id.empty()||id.size()>32||id.find_first_not_of("0123456789")!=id.npos)return {};return directory+"/album-art/"+type+"-"+id+".jpg";}
void CollectionStore::fetchImage(std::string type,std::string id,std::string url){if(imagePath(type,id).empty())return;std::vector<unsigned char> bytes;uint32_t w,h;if(!httpURL(url)||fetch(url,bytes,8*1024*1024,false)!=200||!coverDimensions(bytes,w,h))return;auto staged=imagePath(type,id)+".download";auto *surface=boundedCoverSurface(bytes);if(!surface)return;bytes=remoteCoverJpeg(surface);SDL_FreeSurface(surface);coverWrite(staged,bytes);std::lock_guard<std::mutex> l(mutex);for(auto &entry:data[type=="station"?"stations":type=="playlist"?"playlists":"libraries"])if(entry["id"]==id&&entry.value("logo",std::string{})==url){std::rename(staged.c_str(),imagePath(type,id).c_str());entry["image_revision"]=entry.value("image_revision",0)+1;data["revision"]=data.value("revision",uint64_t(1))+1;std::string error;saveLocked(error);break;}}
void CollectionStore::ensureImage(const std::string &type,const std::string &id){if(imagePath(type,id).empty())return;std::lock_guard<std::mutex> lock(mutex);if(jobs.size()>=32)return;const char *list=type=="station"?"stations":type=="playlist"?"playlists":"libraries";for(auto &entry:data[list])if(entry["id"]==id){auto url=entry.value("logo",std::string{});if(url.empty()||!httpURL(url))return;auto key=type+"/"+id+"/"+url;if(requestedImages.insert(key).second)enqueue([this,type,id,url]{fetchImage(type,id,url);});return;}}
