 {std::lock_guard<std::mutex> l(mutex);for(auto &a:data["albums"])if(a["id"]==id){a["busy"]=false;a["available"]=ok&&!tracks.empty();a["status"]=!ok?"Unavailable: "+error:tracks.empty()?"No supported tracks in this folder.":"";if(ok){a["tracks"]=tracks;if(!a.value("manual",false)){if(!details.album.empty())a["title"]=details.album;if(!details.artist.empty())a["artist"]=details.artist;}if(!cover.empty())a["cover_revision"]=a.value("cover_revision",0)+1;lookup=cover.empty()&&!tracks.empty()&&!a.value("manual",false);lookupTitle=a["title"];artist=a["artist"];if(lookup)a["busy"]=true;}data["revision"]=data.value("revision",uint64_t(1))+1;saveLocked(error);break;}}
