 J matches=J::array();if(status==200)try{auto response=J::parse(bytes);for(auto &v:response["releases"]){std::string credited;for(auto &credit:v.value("artist-credit",J::array())){credited+=credit.value("name",std::string{})+credit.value("joinphrase",std::string{});}matches.push_back({{"id",v.at("id")},{"title",v.value("title","")},{"artist",credited},{"year",v.value("date","")},{"score",v.contains("score")?(v["score"].is_number_integer()?v["score"].get<int>():std::atoi(v["score"].get<std::string>().c_str())):0}});}}catch(...){}
